out=[]; details=[]
for bi in range(8):
 row=[]
 for bj in range(8):
  vals=[grid[i][j] for i in range(3*bi,3*bi+3) for j in range(3*bj,3*bj+3) if grid[i][j]!=5]
  counts={v:vals.count(v) for v in set(vals)}
  row.append(max(counts,key=counts.get) if counts else 5)
  details.append((bi,bj,counts))
 out.append(row)
out, [(i,j,c) for i,j,c in details if len(c)>1]
